import java.util.*;
import java.io.*;

public class Main {
    static long[] countTriplets(long[] queries, long diff) {
        // queries[i] > 0 means insert that value, queries[i] < 0 means remove its absolute value
        // Write your solution here
        return new long[queries.length];
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder all = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) all.append(line).append(' ');
        StringTokenizer st = new StringTokenizer(all.toString());
        int q = Integer.parseInt(st.nextToken());
        long diff = Long.parseLong(st.nextToken());
        long[] queries = new long[q];
        for (int i = 0; i < q; i++) queries[i] = Long.parseLong(st.nextToken());
        long[] res = countTriplets(queries, diff);
        StringBuilder sb = new StringBuilder();
        for (long r : res) sb.append(r).append("\n");
        System.out.print(sb);
    }
}
